     1→/**
     2→ * FreeWire - Graph → FreeLang Light 컴파일러
     3→ * 노드 그래프 JSON → 완성된 .free 파일 문자열 생성
     4→ */
     5→
     6→const { Graph }              = require('../core/graph');
     7→const { toFreelangMarkup }   = require('../core/nodes/component');
     8→const { toFreelangCode: dataToCode }  = require('../core/nodes/data');
     9→const { toFreelangCode: logicToCode } = require('../core/nodes/logic');
    10→const { getBridge }          = require('../core/plugin-bridge');
    11→
    12→class GraphCompiler {
    13→  constructor() {
    14→    this.errors   = [];
    15→    this.warnings = [];
    16→  }
    17→
    18→  /**
    19→   * Graph 인스턴스 또는 JSON → .free 파일 문자열
    20→   * @param {Graph|object} input
    21→   * @returns {{ code: string, errors: string[], warnings: string[] }}
    22→   */
    23→  compile(input) {
    24→    this.errors   = [];
    25→    this.warnings = [];
    26→
    27→    const graph = input instanceof Graph ? input : Graph.fromJSON(input);
    28→    const sorted = graph.topologicalSort();
    29→
    30→    const bridge         = getBridge();
    31→    const propsNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'props');
    32→    const stateNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'state');
    33→    const stdlibNodes    = sorted.filter(n => bridge.isStdlibNode(n));
    34→    const constNodes     = sorted.filter(n => n.type === 'data' && !['props','state'].includes(n.dataType) && !bridge.isStdlibNode(n));
    35→    const logicNodes     = sorted.filter(n => n.type === 'logic');
    36→    const componentNodes = sorted.filter(n => n.type === 'component');
    37→
    38→    if (componentNodes.length === 0) {
    39→      this.warnings.push('component 노드가 없습니다. markup 블록이 비어 있습니다.');
    40→    }
    41→
    42→    // 컴포넌트 이름: 그래프 id 또는 첫 component 이름
    43→    const compName = this._resolveComponentName(graph, componentNodes);
    44→
    45→    const sections = [];
    46→
    47→    // 1) component 헤더
    48→    sections.push(`component ${compName} {`);
    49→
    50→    // 2) props 블록
    51→    const propsBlock = this._buildPropsBlock(propsNodes);
    52→    if (propsBlock) sections.push(propsBlock);
    53→
    54→    // 3) style 블록 (component props에서 수집)
    55→    const styleBlock = this._buildStyleBlock(componentNodes);
    56→    if (styleBlock) sections.push(styleBlock);
    57→
    58→    // 4) script 블록 (state + const + stdlib + logic)
    59→    const scriptBlock = this._buildScriptBlock(stateNodes, constNodes, logicNodes, graph, stdlibNodes);
    60→    if (scriptBlock) sections.push(scriptBlock);
    61→
    62→    // 5) markup 블록
    63→    const markupBlock = this._buildMarkupBlock(componentNodes, graph);
    64→    sections.push(markupBlock);
    65→
    66→    sections.push('}');
    67→
    68→    return {
    69→      code:     sections.join('\n\n'),
    70→      errors:   this.errors,
    71→      warnings: this.warnings,
    72→    };
    73→  }
    74→
    75→  // ─── 내부 빌더 ──────────────────────────────────────────────
    76→
    77→  _resolveComponentName(graph, componentNodes) {
    78→    if (componentNodes.length > 0 && componentNodes[0].props?.name) {
    79→      return componentNodes[0].props.name;
    80→    }
    81→    return graph.id.replace(/[^a-zA-Z0-9]/g, '_') || 'MyComponent';
    82→  }
    83→
    84→  _buildPropsBlock(propsNodes) {
    85→    if (propsNodes.length === 0) return null;
    86→    const lines = propsNodes.map(n => {
    87→      if (!n.props) {
    88→        this.warnings.push(`props 노드 [${n.id}]에 props 객체 없음 - 건너뜀`);
    89→        return null;
    90→      }
    91→      const { name, value, required } = n.props;
    92→      if (!name) {
    93→        this.warnings.push(`props 노드 [${n.id}]에 name 없음 - 건너뜀`);
    94→        return null;
    95→      }
    96→      const req = required ? '' : `= ${JSON.stringify(value ?? null)}`;
    97→      return `  ${name}: ${n.dataType ?? 'any'} ${req}`.trimEnd() + ';';
    98→    }).filter(Boolean);
    99→    return `  props {\n${lines.join('\n')}\n  }`;
   100→  }
   101→
   102→  _buildStyleBlock(componentNodes) {
   103→    const styleLines = [];
   104→    componentNodes.forEach(n => {
   105→      if (!n.props) {
   106→        this.warnings.push(`component 노드 [${n.id}] props 없음 — 스타일 생략`);
   107→        return;
   108→      }
   109→      const p = n.props;
   110→      const selector = `.${n.componentType ?? 'unknown'}`;
   111→      const rules = [];
   112→
   113→      if (p.color)        rules.push(`color: ${p.color}`);
   114→      if (p.background)   rules.push(`background: ${p.background}`);
   115→      if (p.padding)      rules.push(`padding: ${p.padding}`);
   116→      if (p.gap)          rules.push(`gap: ${p.gap}`);
   117→      if (p.fontSize)     rules.push(`font-size: ${p.fontSize}`);
   118→      if (p.borderRadius) rules.push(`border-radius: ${p.borderRadius}`);
   119→      if (p.direction && n.componentType === 'container') {
   120→        rules.push(`display: flex`);
   121→        rules.push(`flex-direction: ${p.direction}`);
   122→      }
   123→
   124→      if (rules.length > 0) {
   125→        styleLines.push(`  ${selector} {`);
   126→        rules.forEach(r => styleLines.push(`    ${r};`));
   127→        styleLines.push(`  }`);
   128→      }
   129→    });
   130→
   131→    if (styleLines.length === 0) return null;
   132→    return `  style {\n${styleLines.join('\n')}\n  }`;
   133→  }
   134→
   135→  _buildScriptBlock(stateNodes, constNodes, logicNodes, graph, stdlibNodes = []) {
   136→    const lines = [];
   137→
   138→    // 상수
   139→    constNodes.forEach(n => {
   140→      if (!n.props?.name) {
   141→        this.warnings.push(`const 노드 [${n.id}] props.name 없음 — 건너뜀`);
   142→        return;
   143→      }
   144→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value ?? null)};`);
   145→    });
   146→
   147→    // 상태
   148→    stateNodes.forEach(n => {
   149→      if (!n.props?.name) {
   150→        this.warnings.push(`state 노드 [${n.id}] props.name 없음 — 건너뜀`);
   151→        return;
   152→      }
   153→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value ?? null)};`);
   154→      lines.push(`  function set_${n.props.name}(v) { ${n.props.name} = v; }`);
   155→    });
   156→
   157→    // stdlib 노드 — PluginBridge가 코드 생성
   158→    if (stdlibNodes.length > 0) {
   159→      const bridge = getBridge();
   160→      lines.push('  // ── stdlib 함수 ──');
   161→      stdlibNodes.forEach(n => {
   162→        const code = bridge.codeGenNode(n);
   163→        // 들여쓰기 맞추기
   164→        code.split('\n').forEach(line => lines.push(`  ${line}`));
   165→      });
   166→    }
   167→
   168→    // 로직 노드 (연결 정보 포함)
   169→    logicNodes.forEach(n => {
   170→      const code = this._logicNodeToScript(n, graph);
   171→      if (code) lines.push(code);
   172→    });
   173→
   174→    if (lines.length === 0) return null;
   175→    return `  script {\n${lines.join('\n')}\n  }`;
   176→  }
   177→
   178→  _logicNodeToScript(node, graph) {
   179→    const { logicType, props } = node;
   180→
   181→    // 입력 연결에서 실제 값/노드 id 추론
   182→    const inEdges = graph.incomingEdges(node.id);
   183→    const getConnected = (portId) => {
   184→      const e = inEdges.find(e => e.to.portId === portId);
   185→      return e ? e.from.nodeId : null;
   186→    };
   187→
   188→    switch (logicType) {
   189→      case 'if': {
   190→        const cond = props.condition || getConnected('condition') || 'true';
   191→        return [
   192→          `  if (${cond}) {`,
   193→          `    // then: ${getConnected('then') || '연결 없음'}`,
   194→          `  } else {`,
   195→          `    // else: ${getConnected('else') || '연결 없음'}`,
   196→          `  }`,
   197→        ].join('\n');
   198→      }
   199→      case 'function':
   200→        return [
   201→          `  function ${props.name}(${(props.params || []).join(', ')}) {`,
   202→          `    ${props.body || 'return null;'}`,
   203→          `  }`,
   204→        ].join('\n');
   205→      case 'map':
   206→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).map(function(${props.itemName}) { return ${props.expression}; });`;
   207→      case 'filter':
   208→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).filter(function(${props.itemName}) { return ${props.condition}; });`;
   209→      case 'reduce':
   210→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).reduce(function(${props.accumName}, ${props.itemName}) { return ${props.expression}; }, ${props.initial});`;
   211→      case 'loop':
   212→        return null; // markup 블록에서 처리
   213→      default:
   214→        this.warnings.push(`알 수 없는 logicType: ${logicType}`);
   215→        return null;
   216→    }
   217→  }
   218→
   219→  _buildMarkupBlock(componentNodes, graph) {
   220→    if (componentNodes.length === 0) {
   221→      return `  markup {\n    <!-- 컴포넌트 없음 -->\n  }`;
   222→    }
   223→
   224→    // 루트 컴포넌트: 다른 노드의 출력을 받지 않는 component
   225→    const childIds = new Set(
   226→      graph.edges
   227→        .filter(e => e.to.portId === 'children' || e.from.portType === 'component')
   228→        .map(e => e.to.nodeId)
   229→    );
   230→    const roots = componentNodes.filter(n => !childIds.has(n.id));
   231→    const renderTargets = roots.length > 0 ? roots : [componentNodes[0]];
   232→
   233→    const lines = ['  markup {'];
   234→    renderTargets.forEach(n => {
   235→      // subtype → componentType 정규화 (API 입력 호환)
   236→      if (!n.componentType && n.subtype) n = { ...n, componentType: n.subtype };
   237→      const markup = toFreelangMarkup(n);
   238→      // 들여쓰기 맞추기
   239→      markup.split('\n').forEach(line => {
   240→        lines.push('  ' + line);
   241→      });
   242→    });
   243→    lines.push('  }');
   244→    return lines.join('\n');
   245→  }
   246→}
   247→
   248→module.exports = { GraphCompiler };
   249→

